-- Generated by scripts/build.py. Edit src/*.luau, then rebuild.
local Core = (function()
-- Pure automation controller. Adapter calls must not yield; Roblox lookups live in Hub.luau.
local Core = {}
Core.__index = Core
Core.ARRIVAL_RADIUS = 50
Core.ARRIVAL_SETTLE = 1.5
Core.ARRIVAL_CLEAR = 1.5
Core.ARRIVAL_RETRY = 3
Core.ARRIVAL_ATTEMPTS = 5

-- Reward/eligibility data supplied from JobsConfig / JobRewards (2026-10-31).
Core.JOBS = {
    { tier = 4, jobType = 1, name = "Extreme", reward = 40000, ascensions = 75 },
    { tier = 10, jobType = 2, name = "Ancient Crystal", reward = 25000, ascensions = 50 },
    { tier = 7, jobType = 1, name = "Long-Haul Cargo", reward = 18000, ascensions = 30 },
    { tier = 9, jobType = 2, name = "Crystal Core", reward = 14000, ascensions = 25 },
    { tier = 3, jobType = 1, name = "Hard", reward = 10000, ascensions = 10 },
    { tier = 6, jobType = 1, name = "City Express", reward = 10000, ascensions = 12 },
    { tier = 8, jobType = 2, name = "Crystal Shards", reward = 6000, ascensions = 8 },
    { tier = 2, jobType = 1, name = "Medium", reward = 5000, ascensions = 4 },
    { tier = 5, jobType = 1, name = "Supply Rush", reward = 4000, ascensions = 3 },
    { tier = 1, jobType = 1, name = "Easy", reward = 1000, ascensions = 0 },
}

function Core.bestJob(ascensions)
    assert(type(ascensions) == "number" and ascensions >= 0 and ascensions < math.huge and ascensions % 1 == 0,
        "Ascension count unavailable · enter your current count on Jobs")
    local best
    for _, candidate in ipairs(Core.JOBS) do
        if ascensions >= candidate.ascensions and (not best or candidate.reward > best.reward
            or candidate.reward == best.reward and candidate.ascensions < best.ascensions) then
            best = candidate
        end
    end
    return best
end

function Core.new(adapter)
    return setmetatable({
        adapter = adapter,
        running = true,
        mode = nil,
        treadmill = "x10",
        enabled = { race = false, ascend = false, buy = false, antiIdle = true },
        status = {},
        due = {},
        failures = {},
        jobs = { phase = "idle" },
        farmPhase = "start",
        deliveries = 0,
        orbRequests = 0,
    }, Core)
end

function Core:report(key, text, problem)
    local old = self.status[key]
    if not old or old.text ~= text or old.problem ~= (problem == true) then
        self.status[key] = { text = text, problem = problem == true }
        if self.adapter.onStatus then
            self.adapter.onStatus(key, text, problem == true)
        end
    end
end

function Core:setMode(mode)
    assert(mode == nil or mode == "farm" or mode == "orbs" or mode == "jobs", "Unknown movement mode")
    if not self.running or self.mode == mode then return end
    if self.mode == "jobs" and self.adapter.stopDeliveryMovement then
        self.adapter.stopDeliveryMovement()
    end
    if self.mode then self:report(self.mode, "Off") end
    self.mode = mode
    self.jobs = { phase = "idle" }
    self.farmPhase = "start"
    self.due.movement = 0
    self.failures.movement = 0
    if mode then self:report(mode, "Starting…") end
end

function Core:setEnabled(key, value)
    assert(self.enabled[key] ~= nil, "Unknown automation")
    if not self.running then return end
    self.enabled[key] = value == true
    self.due[key] = 0
    self.failures[key] = 0
    self:report(key, value and "Ready" or "Off")
end

function Core:stopAll()
    self:setMode(nil)
    for key in pairs(self.enabled) do self:setEnabled(key, false) end
end

function Core:destroy()
    if not self.running then return end
    self:stopAll()
    self.running = false
end

function Core:run(key, statusKey, now, callback)
    if now < (self.due[key] or 0) then return end
    local ok, delay = pcall(callback)
    if ok then
        self.failures[key] = 0
        self.due[key] = now + (delay or 1)
    else
        if statusKey == "jobs" then
            -- An unreadable sample is not evidence of continuous proximity/completion.
            self.jobs.withinSince = nil
            self.jobs.arrivalClearSince = nil
            self.jobs.clearSince = nil
        end
        local failures = (self.failures[key] or 0) + 1
        self.failures[key] = failures
        local retry = math.min(15, 2 ^ math.min(failures - 1, 4))
        self.due[key] = now + retry
        self:report(statusKey, tostring(delay) .. " · retry in " .. retry .. "s", true)
    end
end

function Core:stepJobs(now)
    local job = self.jobs
    local gamePhase = self.adapter.getJobPhase and self.adapter.getJobPhase()
    local drop
    if gamePhase == nil or gamePhase == "running" then drop = self.adapter.getDropPoint() end
    -- The game's DeliveryAutoLockController only uses GetDropPoint in "running".
    -- A claimed contract must leave its pad normally before teleporting to its target.
    if gamePhase == "claimed" then
        job.phase = "leavePad"
        job.leaveStarted = job.leaveStarted or now
        if now - job.leaveStarted >= 12 then
            if not job.leavePaused then self.adapter.stopDeliveryMovement(); job.leavePaused = true end
            self:report("jobs", "Job still claimed · step off the job pad manually to start running", true)
            return 1
        end
        if now >= (job.nextLeave or 0) then
            self.adapter.leaveJobPad()
            job.nextLeave = now + 4
        end
        self:report("jobs", "Job claimed · leaving pad normally; waiting for running phase")
        return 0.5
    end
    if job.phase == "leavePad" then
        self.adapter.stopDeliveryMovement()
        self.jobs = { phase = "idle" }
        job = self.jobs
    end
    if gamePhase ~= nil and gamePhase ~= "running" then drop = nil end
    if gamePhase == "running" and self.adapter.getPlayerState then
        local playerState = self.adapter.getPlayerState()
        if playerState ~= "RunWorld" then
            if not job.worldPaused then self.adapter.stopDeliveryMovement(); job.worldPaused = true end
            job.withinSince = nil
            job.arrivalClearSince = nil
            job.clearSince = nil
            self:report("jobs", "Waiting for running world before delivery movement")
            return 0.5
        end
        job.worldPaused = nil
    end
    if drop ~= nil then job.lastDrop = drop end

    if job.phase == "approach" or job.phase == "awaitArrival" then
        -- A game-side completion can move the player too. Once arrival was reported,
        -- observe a cleared destination before considering any position corrections.
        if job.phase == "awaitArrival" and drop == nil then
            job.arrivalClearSince = job.arrivalClearSince or now
            if now - job.arrivalClearSince >= Core.ARRIVAL_CLEAR then
                job.phase = "collect"
                self:report("jobs", "Destination cleared · ready to collect banked payout")
            else
                self:report("jobs", "Destination cleared · checking it stays cleared")
            end
            return 0.3
        end
        job.arrivalClearSince = nil
        local distance = self.adapter.getDropDistance(job.lastDrop)
        assert(type(distance) == "number" and distance >= 0 and distance < math.huge, "Delivery distance unavailable")
        local attempts = job.arrivalAttempts or 0
        local detail = string.format("%.1f / %d studs · arrival %d/%d", distance, Core.ARRIVAL_RADIUS, attempts, Core.ARRIVAL_ATTEMPTS)

        if distance > Core.ARRIVAL_RADIUS then
            job.withinSince = nil
            job.arrivalClearSince = nil
            local diagnostic, returned
            if self.adapter.getDeliveryDiagnostics then
                diagnostic, returned = self.adapter.getDeliveryDiagnostics(job.lastDrop)
            end
            if returned and job.travelMode ~= "walk" and self.adapter.walkToDrop then
                self.adapter.stopDeliveryMovement()
                job.travelMode = "walk"
                job.bestWalkDistance = distance
                job.lastWalkProgress = now
                job.nextWalk = 0
                self:report("jobs", "Teleport returned to starting area · switching to normal movement", true)
            end
            if job.travelMode == "walk" then
                if distance < job.bestWalkDistance - 2 then
                    job.bestWalkDistance = distance
                    job.lastWalkProgress = now
                end
                if not job.movementBlocked and now - job.lastWalkProgress >= 12 then
                    self.adapter.stopDeliveryMovement()
                    job.movementBlocked = true
                end
                if job.movementBlocked then
                    self:report("jobs", string.format("Normal movement stalled · %.0f studs away · use game controls to reach marker", distance), true)
                    return 1
                end
                if now >= job.nextWalk then
                    self.adapter.walkToDrop(job.lastDrop)
                    job.nextWalk = now + 4 -- Humanoid MoveTo times out after eight seconds.
                end
                self:report("jobs", string.format("Normal movement after teleport reset · %.0f studs to delivery", distance))
                return 0.5
            end
            if (job.repositions or 0) < 3 and now >= (job.nextReposition or 0) then
                local moved, message, problem = self.adapter.moveToDrop(job.lastDrop)
                if moved == false then
                    self:report("jobs", message, problem)
                    return 0.5
                end
                job.repositions = (job.repositions or 0) + 1
                job.nextReposition = now + 3
                self:report("jobs", "Repositioned · checking whether the move holds")
                return 0.3
            end
            if (job.repositions or 0) >= 3 and not job.movementBlocked then
                self.adapter.stopDeliveryMovement()
                job.movementBlocked = true
            end
            self:report("jobs", (job.movementBlocked and "Movement paused · " or "Checking move · ") .. (diagnostic or detail), true)
            return job.movementBlocked and 1 or 0.3
        end
        job.movementBlocked = nil
        job.withinSince = job.withinSince or now
        if now - job.withinSince < Core.ARRIVAL_SETTLE then
            self:report("jobs", "Letting position settle · " .. detail)
            return 0.3
        end

        if attempts >= Core.ARRIVAL_ATTEMPTS then
            self:report("jobs", "Arrival unconfirmed · " .. detail .. " · try walking to marker", true)
            return 0.5
        end
        if now >= (job.nextArrival or 0) then
            self.adapter.reportArrival()
            job.arrivalAttempts = attempts + 1
            job.nextArrival = now + Core.ARRIVAL_RETRY
            job.phase = "awaitArrival"
            self:report("jobs", string.format("Arrival sent · %.1f / %d studs · attempt %d/%d; awaiting game", distance, Core.ARRIVAL_RADIUS, job.arrivalAttempts, Core.ARRIVAL_ATTEMPTS))
        else
            self:report("jobs", "Awaiting arrival · " .. detail)
        end
        return 0.3
    elseif job.phase == "collect" then
        if drop ~= nil then
            job.phase = "awaitArrival"
            job.arrivalClearSince = nil
            self:report("jobs", "Destination active again · waiting for arrival acceptance")
            return 0.3
        end
        if (job.collections or 0) >= 3 then
            self:report("jobs", "Payout state keeps changing · holding delivery; restart Jobs to retry", true)
            return 1
        end
        self.adapter.collectJob()
        job.collections = (job.collections or 0) + 1
        job.phase = "confirm"
        job.clearSince = nil
        self:report("jobs", "Payout requested · confirming delivery cleared")
        return 0.3
    elseif job.phase == "confirm" then
        if drop == nil then
            job.clearSince = job.clearSince or now
            if now - job.clearSince >= 3 then
                self.adapter.stopDeliveryMovement()
                self.deliveries = self.deliveries + 1
                self.jobs = { phase = "idle" }
                self:report("jobs", "Delivery cleared · next job in 2s")
                return 2
            end
            self:report("jobs", "Confirming delivery cleared · staying at destination")
        else
            job.clearSince = nil
            job.arrivalClearSince = nil
            job.phase = "awaitArrival"
            self:report("jobs", "Destination active again · holding this delivery")
        end
        return 0.3
    end

    if drop ~= nil then
        local moved, message, problem = self.adapter.moveToDrop(drop)
        if moved == false then
            self:report("jobs", message, problem)
            return 0.5
        end
        job.phase = "approach"
        job.nextReposition = now + 3
        self:report("jobs", "Approaching delivery · waiting for position to settle")
        return 0.3
    end
    if job.phase == "waiting" then
        if now >= job.deadline then
            self:report("jobs", "Claim not confirmed · waiting; restart Jobs to retry", true)
        end
        -- A timeout is not a rejection. Never downgrade or send another claim blindly.
        return 0.3
    end
    if gamePhase ~= nil and gamePhase ~= "idle" then
        self:report("jobs", "Game job phase: " .. tostring(gamePhase) .. " · waiting before a new claim")
        return 0.5
    end

    local candidate = Core.bestJob(self.adapter.getAscensions())
    if job.phase ~= "claim" then
        self.adapter.moveToBoard()
        job.phase = "claim"
        self:report("jobs", "At board · selected " .. candidate.name .. " (" .. candidate.reward .. ")")
        return 0.8
    end
    -- Recheck eligibility immediately before the request; ascension may have changed.
    self.adapter.claimJob(candidate.tier, candidate.jobType)
    job.choice = candidate
    job.phase = "waiting"
    job.deadline = now + 12
    self:report("jobs", "Requested " .. candidate.name .. " · waiting for acceptance")
    return 0.3
end

function Core:tick(now)
    if not self.running then return end
    if self.mode then
        self:run("movement", self.mode, now, function()
            if self.mode == "jobs" then return self:stepJobs(now) end
            if self.mode == "farm" then
                self.adapter.moveToTreadmill(self.treadmill)
                if self.farmPhase == "start" then
                    self.adapter.chargeStart()
                    self.farmPhase = "burst"
                    self:report("farm", "Charging on " .. self.treadmill)
                    return 0.4
                end
                self.adapter.chargeBurst()
                self.farmPhase = "start"
                self:report("farm", "Training on " .. self.treadmill)
                return 0.8
            end
            local found = self.adapter.collectNearestOrb()
            if found then self.orbRequests = self.orbRequests + 1 end
            self:report("orbs", found and "Nearby orb requested" or "No collectible orbs within 80 studs")
            return 0.8
        end)
    end
    for _, key in ipairs({ "race", "ascend", "buy" }) do
        if self.enabled[key] then
            self:run(key, key, now, function()
                if self.mode == "jobs" and key ~= "buy" then
                    self:report(key, "Paused while jobs control movement")
                    return 1
                end
                if key == "race" then
                    self.adapter.resetRace()
                    self:report(key, "Race reset requested")
                    return 4
                elseif key == "ascend" then
                    self.adapter.ascend()
                    self:report(key, "Ascension requested")
                    return 10
                end
                self.adapter.buyUpgrades()
                self:report(key, "Speed / Jump purchase requests sent")
                return 5
            end)
        end
    end
end

return Core

end)()

-- Roblox client adapter and UI. Core is embedded above this file by scripts/build.py.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")
local Input = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local player = Players.LocalPlayer
assert(player, "Speedsters Beyond must be loaded on the client")
local playerGui = player:WaitForChild("PlayerGui", 10)
assert(playerGui, "PlayerGui did not load; retry after joining the game")

local shared = type(getgenv) == "function" and getgenv() or _G
local previous = shared.SpeedstersBeyondSession
if type(previous) == "table" and type(previous.destroy) == "function" then
    pcall(previous.destroy)
end
-- Quiesce the feature flags used by the user's original script when upgrading in-session.
for _, key in ipairs({ "AutoFarmState", "AutoOrbsState", "AutoJobState", "AutoRaceState", "AutoAscendState", "AutoBuyState" }) do
    if shared[key] ~= nil then shared[key] = false end
end

local parentGui = playerGui
local ok, hiddenGui = pcall(function()
    return type(gethui) == "function" and gethui() or game:GetService("CoreGui")
end)
if ok and hiddenGui then
    local probe = Instance.new("Folder")
    local writable = pcall(function() probe.Parent = hiddenGui end)
    probe:Destroy()
    if writable then parentGui = hiddenGui end
end
for _, parent in ipairs(parentGui == playerGui and { playerGui } or { playerGui, parentGui }) do
    local old = parent:FindFirstChild("SpeedstersBeyondHub")
    if old then
        local shutdown = old:FindFirstChild("Shutdown")
        if shutdown and shutdown:IsA("BindableEvent") then shutdown:Fire() end
        old:Destroy()
    end
end

local session = { alive = true, connections = {}, threads = {}, tweens = {} }
shared.SpeedstersBeyondSession = session
local engine
local gui
local function connect(signal, callback)
    local connection = signal:Connect(function(...)
        if session.alive then callback(...) end
    end)
    table.insert(session.connections, connection)
    return connection
end
function session.destroy()
    if not session.alive then return end
    session.alive = false
    if engine then engine:destroy() end
    for _, connection in ipairs(session.connections) do connection:Disconnect() end
    for _, thread in ipairs(session.threads) do
        if coroutine.status(thread) ~= "dead" then pcall(task.cancel, thread) end
    end
    for _, tween in pairs(session.tweens) do tween:Cancel() end
    if gui then gui:Destroy() end
    if shared.SpeedstersBeyondSession == session then shared.SpeedstersBeyondSession = nil end
end

local palette = {
    bg = Color3.fromRGB(12, 16, 25),
    panel = Color3.fromRGB(18, 24, 37),
    card = Color3.fromRGB(23, 31, 46),
    stroke = Color3.fromRGB(45, 59, 78),
    text = Color3.fromRGB(237, 244, 255),
    muted = Color3.fromRGB(151, 170, 193),
    accent = Color3.fromRGB(83, 238, 205),
    blue = Color3.fromRGB(92, 156, 255),
    purple = Color3.fromRGB(164, 126, 255),
    warning = Color3.fromRGB(255, 193, 111),
    red = Color3.fromRGB(255, 116, 139),
}
local function create(class, props, parent)
    local object = Instance.new(class)
    for key, value in pairs(props or {}) do object[key] = value end
    object.Parent = parent
    return object
end
local function round(object, radius)
    local corner = object:FindFirstChildOfClass("UICorner") or create("UICorner", {}, object)
    corner.CornerRadius = UDim.new(0, radius or 12)
end
local function stroke(object, color, transparency)
    return create("UIStroke", { Color = color or palette.stroke, Transparency = transparency or 0, Thickness = 1 }, object)
end
local function animate(object, props)
    -- Keep at most one tween per widget; rapid toggles cannot finish out of order.
    if session.tweens[object] then session.tweens[object]:Cancel() end
    local tween = TweenService:Create(object, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
    session.tweens[object] = tween
    tween:Play()
end
local function label(parent, text, size, color, bold)
    return create("TextLabel", {
        BackgroundTransparency = 1, BorderSizePixel = 0, Text = text,
        Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham,
        TextSize = size or 13, TextColor3 = color or palette.text,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, parent)
end
local function button(parent, text, color)
    local item = create("TextButton", {
        BorderSizePixel = 0, BackgroundColor3 = color or palette.card,
        TextColor3 = palette.text, Font = Enum.Font.GothamMedium, TextSize = 13,
        Text = text, AutoButtonColor = false,
    }, parent)
    round(item, 8)
    connect(item.MouseEnter, function() animate(item, { BackgroundTransparency = 0.2 }) end)
    connect(item.MouseLeave, function() animate(item, { BackgroundTransparency = 0 }) end)
    return item
end
local function padding(parent, amount)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, amount), PaddingRight = UDim.new(0, amount),
        PaddingTop = UDim.new(0, amount), PaddingBottom = UDim.new(0, amount),
    }, parent)
end
local function stack(parent, gap)
    create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, gap or 10) }, parent)
end

local events = {}
local eventLabel
local startedAt = os.clock()
local function log(text, problem)
    table.insert(events, 1, string.format("%02d:%02d  %s", math.floor((os.clock() - startedAt) / 60), math.floor((os.clock() - startedAt) % 60), text))
    while #events > 6 do table.remove(events) end
    if eventLabel then eventLabel.Text = table.concat(events, "\n") end
    if problem then warn("[Speedsters Beyond] " .. text) end
end

local function remote(name)
    local folder = ReplicatedStorage:FindFirstChild("Remotes")
    local item = folder and folder:FindFirstChild(name)
    if not item or not item:IsA("RemoteEvent") then error("Missing RemoteEvent: " .. name, 0) end
    return item
end
local function send(name, ...)
    remote(name):FireServer(...)
end
local function root()
    local character = player.Character
    local part = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not part or not part:IsA("BasePart") or not humanoid or humanoid.Health <= 0 then
        error("Waiting for a living character", 0)
    end
    return part
end
local function location(value)
    local kind = typeof(value)
    if kind == "Vector3" then return CFrame.new(value) end
    if kind == "CFrame" then return value end
    if kind == "Instance" then
        if value:IsA("BasePart") then return value.CFrame end
        if value:IsA("Attachment") then return value.WorldCFrame end
        if value:IsA("Model") and value:FindFirstChildWhichIsA("BasePart", true) then return value:GetPivot() end
    end
    error("Unsupported or missing destination", 0)
end
local function moveTo(value, distance, offset)
    local part = root()
    local target = location(value)
    if (part.Position - target.Position).Magnitude > distance then
        part.CFrame = target + Vector3.new(0, offset or 3, 0)
        part.AssemblyLinearVelocity = Vector3.zero
        part.AssemblyAngularVelocity = Vector3.zero
    end
end

local deliveryHumanoid
local deliveryPreparation
local lastDeliveryMove
local function cancelPreparation()
    local previous = deliveryPreparation
    deliveryPreparation = nil
    if previous and previous.thread and coroutine.status(previous.thread) ~= "dead" then
        pcall(task.cancel, previous.thread)
    end
end
local function stopDeliveryMovement()
    cancelPreparation()
    lastDeliveryMove = nil
    local humanoid = deliveryHumanoid
    deliveryHumanoid = nil
    if humanoid and humanoid.Parent then
        local part = humanoid.Parent:FindFirstChild("HumanoidRootPart")
        if part then humanoid:MoveTo(part.Position) end
    end
end
local function prepareDeliveryArea(target, character)
    local current = deliveryPreparation
    if not current or current.character ~= character or (current.target - target).Magnitude > 5 then
        cancelPreparation()
        current = { target = target, character = character, started = os.clock(), streamed = not workspace.StreamingEnabled }
        deliveryPreparation = current
        if workspace.StreamingEnabled then
            -- Streaming can yield. The worker only loads terrain; movement stays in the
            -- cancellable controller tick, so a late result cannot teleport after Stop.
            current.thread = task.spawn(function()
                local loaded, err = pcall(function() player:RequestStreamAroundAsync(target, 5) end)
                if deliveryPreparation ~= current or not session.alive then return end
                current.streamed = true
                if not loaded then current.streamError = tostring(err) end
            end)
        end
    end
    if not current.streamed and os.clock() - current.started < 2 then
        return nil, "Preparing delivery area · waiting up to 2 seconds", false
    end
    -- A raycast cannot prove that a delivery point is unusable: the surface can be
    -- streamed out, non-queryable, sloped, or offset from the marker. Treat it only
    -- as a landing-height hint and retain the game's own destination as fallback.
    local fallback = target + Vector3.new(0, 3, 0)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { character }
    params.RespectCanCollide = true
    local queried, hit = pcall(function()
        return workspace:Raycast(target + Vector3.new(0, 40, 0), Vector3.new(0, -90, 0), params)
    end)
    if not queried or not hit or hit.Normal.Y < 0.5 then return fallback end
    local part = root()
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local standingHeight = humanoid.HipHeight + part.Size.Y / 2 + 0.5
    local landing = Vector3.new(target.X, hit.Position.Y + standingHeight, target.Z)
    if (landing - target).Magnitude > Core.ARRIVAL_RADIUS then return fallback end
    return landing
end
local function approachDelivery(drop)
    local part = root()
    local character = part.Parent
    local target = location(drop).Position
    local before = part.Position
    if (before - target).Magnitude > Core.ARRIVAL_RADIUS then
        local landing, message, problem = prepareDeliveryArea(target, character)
        if not landing then return false, message, problem end
        -- Translate the complete character while preserving the root-to-pivot offset.
        character:PivotTo(character:GetPivot() + (landing - before))
        part.AssemblyLinearVelocity = Vector3.zero
        part.AssemblyAngularVelocity = Vector3.zero
        lastDeliveryMove = { target = target, before = before, placed = part.Position, time = os.clock(), distance = (part.Position - target).Magnitude }
        if lastDeliveryMove.distance > Core.ARRIVAL_RADIUS then
            return false, string.format("Move did not reach delivery: %.1f studs remain", lastDeliveryMove.distance), true
        end
    end
    deliveryHumanoid = character:FindFirstChildOfClass("Humanoid")
    deliveryHumanoid:MoveTo(target)
    return true
end
local function deliveryDiagnostics(drop)
    local part = root()
    local target = location(drop).Position
    local delta = part.Position - target
    local horizontal = math.sqrt(delta.X * delta.X + delta.Z * delta.Z)
    local explanation = "Position remains outside delivery radius"
    local returned = false
    if lastDeliveryMove then
        local targetShift = (target - lastDeliveryMove.target).Magnitude
        if targetShift > Core.ARRIVAL_RADIUS then
            explanation = string.format("Delivery target changed by %.0f studs", targetShift)
        elseif lastDeliveryMove.distance <= Core.ARRIVAL_RADIUS then
            local originalDistance = (lastDeliveryMove.before - target).Magnitude
            local nearOrigin = (part.Position - lastDeliveryMove.before).Magnitude <= math.max(25, math.min(100, originalDistance * 0.05))
            returned = nearOrigin and (part.Position - lastDeliveryMove.placed).Magnitude > Core.ARRIVAL_RADIUS
            if returned then
                explanation = "Character returned to its pre-teleport position"
            elseif delta.Y < -50 and part.AssemblyLinearVelocity.Y < -5 then
                explanation = "Character is falling below delivery ground"
            else
                explanation = "Character moved away after a successful local reposition"
            end
        end
    end
    return string.format("%s · horizontal %.0f, vertical %+.0f studs · player (%.0f, %.0f, %.0f), target (%.0f, %.0f, %.0f)",
        explanation, horizontal, delta.Y, part.Position.X, part.Position.Y, part.Position.Z, target.X, target.Y, target.Z), returned
end

local controller = { script = nil, value = nil, loading = false, retry = 0, failure = nil }
local function jobsController()
    local scripts = player:FindFirstChild("PlayerScripts")
    local controllers = scripts and scripts:FindFirstChild("Controllers")
    local module = controllers and controllers:FindFirstChild("JobsController")
    if not module or not module:IsA("ModuleScript") then error("Waiting for JobsController", 0) end
    if controller.script ~= module then
        controller = { script = module, value = nil, loading = false, retry = 0, failure = nil }
    end
    local current = controller
    if current.value then return current.value end
    if not current.loading and os.clock() >= current.retry then
        current.loading = true
        current.started = os.clock()
        -- require can yield; keep it out of the shared automation loop.
        local thread = task.spawn(function()
            local loaded, result = pcall(require, module)
            if not session.alive or controller ~= current then return end
            current.loading = false
            current.retry = os.clock() + 10
            if loaded and type(result) == "table" and type(result.GetDropPoint) == "function" then
                current.value = result
            else
                current.failure = loaded and "JobsController has no GetDropPoint method" or "JobsController could not load"
                log(current.failure, true)
            end
        end)
        table.insert(session.threads, thread)
    end
    if current.value then return current.value end
    if current.loading and os.clock() - current.started > 10 then
        error("JobsController is still loading; rejoin if this persists", 0)
    end
    error(current.failure or "Loading JobsController", 0)
end

local ascensionOverride
local function readAscensions()
    if ascensionOverride ~= nil then return ascensionOverride, "manual" end
    local detected
    local function consider(value)
        local number = tonumber(value)
        if not number or number < 0 or number >= math.huge or number % 1 ~= 0 then return end
        if detected ~= nil and detected ~= number then
            error("Conflicting ascension counts · enter your current count below", 0)
        end
        detected = number
    end
    consider(player:GetAttribute("Ascensions"))
    consider(player:GetAttribute("Ascension"))
    -- Attribute and ValueObject paths differ across game versions. Never default a missing stat to 0.
    for _, item in ipairs(player:GetDescendants()) do
        local name = string.lower(item.Name)
        if (name == "ascensions" or name == "ascension") and (item:IsA("IntValue") or item:IsA("NumberValue") or item:IsA("StringValue")) then
            consider(item.Value)
        end
    end
    if detected == nil then error("Ascensions unavailable · enter your current count below", 0) end
    return detected, "detected"
end

local orbParts = {}
local orbCooldown = setmetatable({}, { __mode = "k" })
local orbsIndexed = false
local function indexOrb(object)
    if object:IsA("BasePart") and string.find(string.lower(object.Name), "orb", 1, true) then
        orbParts[object] = true
    end
end
local function ensureOrbIndex()
    if orbsIndexed then return end
    orbsIndexed = true
    connect(workspace.DescendantAdded, indexOrb)
    connect(workspace.DescendantRemoving, function(object) orbParts[object] = nil end)
    for _, object in ipairs(workspace:GetDescendants()) do indexOrb(object) end
end

local nextWarning = {}
engine = Core.new({
    onStatus = function(key, text, problem)
        -- UI status stays live; changing distances must not flood the console/feed.
        if problem and os.clock() >= (nextWarning[key] or -math.huge) then
            nextWarning[key] = os.clock() + 5
            log(key .. ": " .. text, true)
        end
    end,
    moveToTreadmill = function(name)
        remote("ChargeStart")
        remote("ChargeBurst")
        local folder = workspace:FindFirstChild("Treadmills")
        local target = folder and folder:FindFirstChild(name)
        if not target then error("Treadmill " .. name .. " is unavailable; select another", 0) end
        moveTo(target, 7, 3)
    end,
    chargeStart = function() send("ChargeStart") end,
    chargeBurst = function() send("ChargeBurst") end,
    getAscensions = readAscensions,
    getDropPoint = function()
        root()
        local value = jobsController():GetDropPoint()
        if value == nil or value == false then return nil end
        return location(value)
    end,
    getJobPhase = function()
        root()
        local jobs = jobsController()
        if type(jobs.GetPhase) ~= "function" then error("JobsController phase API is unavailable", 0) end
        local phase = jobs:GetPhase()
        if type(phase) ~= "string" or phase == "" then error("Waiting for job phase to load", 0) end
        return phase
    end,
    getPlayerState = function()
        return player.Character and player.Character:GetAttribute("PlayerState")
    end,
    leaveJobPad = function()
        local part = root()
        deliveryHumanoid = part.Parent:FindFirstChildOfClass("Humanoid")
        deliveryHumanoid:MoveTo(part.Position + part.CFrame.LookVector * 16)
    end,
    moveToBoard = function()
        local geometry = workspace:FindFirstChild("ServerGeometry")
        local board = workspace:FindFirstChild("JobsPart") or (geometry and geometry:FindFirstChild("JobsPart"))
        if not board then error("Waiting for the job board to load", 0) end
        -- Verify all three endpoints before accepting a delivery we cannot finish.
        remote("ClaimJob")
        remote("ReportJobArrival")
        remote("CollectJob")
        moveTo(board, 10, 3)
    end,
    claimJob = function(tier, slot) send("ClaimJob", tier, slot) end,
    moveToDrop = approachDelivery,
    getDeliveryDiagnostics = deliveryDiagnostics,
    walkToDrop = function(drop)
        local part = root()
        deliveryHumanoid = part.Parent:FindFirstChildOfClass("Humanoid")
        deliveryHumanoid:MoveTo(location(drop).Position)
    end,
    getDropDistance = function(drop) return (root().Position - location(drop).Position).Magnitude end,
    stopDeliveryMovement = stopDeliveryMovement,
    reportArrival = function() send("ReportJobArrival") end,
    collectJob = function() send("CollectJob") end,
    collectNearestOrb = function()
        local origin = root().Position
        local collect = remote("OrbCollect")
        ensureOrbIndex()
        local nearest, nearestDistance = nil, 80
        local now = os.clock()
        for object in pairs(orbParts) do
            if object:IsDescendantOf(workspace) and now >= (orbCooldown[object] or 0) then
                local distance = (origin - object.Position).Magnitude
                if distance < nearestDistance then nearest, nearestDistance = object, distance end
            end
        end
        if not nearest then return false end
        moveTo(nearest, 3, 0)
        collect:FireServer(nearest)
        orbCooldown[nearest] = now + 5
        return true
    end,
    resetRace = function() root(); send("ResetRace") end,
    ascend = function() root(); send("AscendRequest") end,
    buyUpgrades = function()
        local buy = remote("BuyUpgrade")
        buy:FireServer("Speed")
        buy:FireServer("Jump")
    end,
})
session.engine = engine

